const schema = [{"@context":"https://schema.org","@type":"Service","name":"Digital production QA","serviceType":"Publishing service","provider":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"},"url":"https://pubrica.com/services/education-editorial-service/digital-production-qa-services/","description":"Independent QA on proofs, XML, metadata and final files — JATS validation, cross-format consistency, reference and link integrity.","areaServed":"Worldwide","audience":{"@type":"Audience","audienceType":"Researchers, PhD scholars, research institutions, medical writers and life-science teams"}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Why is production QA worth buying separately?","acceptedAnswer":{"@type":"Answer","text":"Because nobody finds their own errors reliably. QA performed by whoever produced the files is a second look by the same eyes, and it misses the same things twice.\n\nThe specific gain is cross-format checking. Most surviving errors are not mistakes inside a file — they are disagreements between the PDF, the XML, the HTML and the EPUB, and a single-format check cannot see them."}},{"@type":"Question","name":"Do you review XML and metadata?","acceptedAnswer":{"@type":"Answer","text":"Yes, validated against your DTD or JATS, and checked against what the indexing platforms actually require rather than what the schema permits.\n\nValid XML that fails PubMed Central is common and frustrating, because nothing looks wrong. That is the sort of thing this check exists for."}},{"@type":"Question","name":"Can you audit content that is already published?","acceptedAnswer":{"@type":"Answer","text":"Yes. Live content on journal and repository platforms is audited, findings are located and graded, and corrections are supported through your platform’s process.\n\nFor most publishers it is the first time anyone has looked, and the first audit is always the interesting one."}},{"@type":"Question","name":"Who can use this?","acceptedAnswer":{"@type":"Answer","text":"Academic publishers, journal editorial teams, authors and researchers, universities, repositories and production vendors.\n\nVendors are genuinely welcome. An independent check on your own output is easier to offer a client than asking them to trust your internal one."}},{"@type":"Question","name":"What if the QA finds major errors?","acceptedAnswer":{"@type":"Answer","text":"You get detailed correction guidance for each one — the location, the severity and what to do — and we support your production team while they work through it.\n\nThen the final validation pass confirms each fix was made, and made in every format. That second check catches a surprising amount."}},{"@type":"Question","name":"Is this the same as copyediting?","acceptedAnswer":{"@type":"Answer","text":"No. Production QA checks the file: layout, formatting, XML, metadata, links and consistency across outputs. It does not edit prose.\n\nAnd it does not audit the research. Publication ethics, data integrity and reporting-guideline compliance are a different service with a different team."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Services","item":"https://pubrica.com/services/"},{"@type":"ListItem","position":3,"name":"Education editorial","item":"https://pubrica.com/services/education-editorial-service/digital-production-qa-services/"}]}];

